{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Tetrabenazine, the closest non-prodrug structural analog, has a mean oral systemic availability of 0.049 ± 0.032 in patients, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Valbenazine, a VMAT2 inhibitor prodrug, has an absolute oral bioavailability of approximately 49%, above the threshold; however, its prodrug structure enhances absorption and is not representative of a non-prodrug tetrabenazine-like scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Almorexant has an absolute oral bioavailability of about 11%, below the threshold, providing additional but lower-transferability support for low bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest structural evidence from tetrabenazine shows very low oral bioavailability (<5%), strongly supporting a low prediction for a non-prodrug tetrabenazine-like query. Valbenazine's high bioavailability reflects prodrug design and is less transferable, while other evidence is from less related chemical families.",
  "evidence_gaps": [
    "Query structure/identity is not provided, so direct structural similarity to tetrabenazine versus valbenazine cannot be confirmed.",
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "Valbenazine's prodrug mechanism introduces uncertainty in extrapolating its high bioavailability to non-prodrug analogs."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C18"],
      "decision_effect": "strengthened",
      "direction": "supportive",
