    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "valbenazine prodrug"
    },
    {
      "applicability": "low",
      "card_ids": ["C30"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "orexin receptor antagonists"
    }
  ],
  "revision_action": "initial"
}

